   295  /**
   296   * Safe but slow version of gridDiskDistances (also called by it when needed).
   297   *
   298   * Adds the origin cell to the output set (treating it as a hash set)
   299   * and recurses to its neighbors, if needed.
   300   *
   301   * @param  origin      Origin cell
   302   * @param  k           Maximum distance to move from the origin
   303   * @param  out         Array treated as a hash set, elements being either
   304   *                     H3Index or 0.
   305   * @param  distances   Scratch area, with elements paralleling the out array.
   306   *                     Elements indicate ijk distance from the origin cell to
   307   *                     the output cell
   308   */
   309  H3Error H3_EXPORT(gridDiskDistancesSafe)(H3Index origin, int k, H3Index *out,
   310                                           int *distances) {
   311      int64_t maxIdx;
   312      H3Error err = H3_EXPORT(maxGridDiskSize)(k, &maxIdx);
   313      if (err) {
   314          return err;
   315      }
   316      return _gridDiskDistancesInternal(origin, k, out, distances, maxIdx, 0);
   317  }
