   319  /**
   320   * Returns the hexagon index neighboring the origin, in the direction dir.
   321   *
   322   * Implementation note: The only reachable case where this returns 0 is if the
   323   * origin is a pentagon and the translation is in the k direction. Thus,
   324   * 0 can only be returned if origin is a pentagon.
   325   *
   326   * @param origin Origin index
   327   * @param dir Direction to move in
   328   * @param rotations Number of ccw rotations to perform to reorient the
   329   *                  translation vector. Will be modified to the new number of
   330   *                  rotations to perform (such as when crossing a face edge.)
   331   * @param out H3Index of the specified neighbor if succesful
   332   * @return E_SUCCESS on success
   333   */
   334  H3Error h3NeighborRotations(H3Index origin, Direction dir, int *rotations,
   335                              H3Index *out) {
   336      H3Index current = origin;
   337
   338      if (dir < CENTER_DIGIT || dir >= INVALID_DIGIT) {
   339          return E_FAILED;
   340      }
   341      for (int i = 0; i < *rotations; i++) {
   342          dir = _rotate60ccw(dir);
   343      }
   344
   345      int newRotations = 0;
   346      int oldBaseCell = H3_GET_BASE_CELL(current);
   347      if (oldBaseCell < 0 ||  // LCOV_EXCL_BR_LINE
   348          oldBaseCell >= NUM_BASE_CELLS) {
   349          // Base cells less than zero can not be represented in an index
   350          return E_CELL_INVALID;
   351      }
   352      Direction oldLeadingDigit = _h3LeadingNonZeroDigit(current);
   353
   354      // Adjust the indexing digits and, if needed, the base cell.
   355      int r = H3_GET_RESOLUTION(current) - 1;
   356      while (true) {
   357          if (r == -1) {
   358              H3_SET_BASE_CELL(current, baseCellNeighbors[oldBaseCell][dir]);
   359              newRotations = baseCellNeighbor60CCWRots[oldBaseCell][dir];
   360
   361              if (H3_GET_BASE_CELL(current) == INVALID_BASE_CELL) {
   362                  // Adjust for the deleted k vertex at the base cell level.
   363                  // This edge actually borders a different neighbor.
   364                  H3_SET_BASE_CELL(current,
   365                                   baseCellNeighbors[oldBaseCell][IK_AXES_DIGIT]);
   366                  newRotations =
   367                      baseCellNeighbor60CCWRots[oldBaseCell][IK_AXES_DIGIT];
   368
   369                  // perform the adjustment for the k-subsequence we're skipping
   370                  // over.
   371                  current = _h3Rotate60ccw(current);
   372                  *rotations = *rotations + 1;
   373              }
   374
   375              break;
   376          } else {
   377              Direction oldDigit = H3_GET_INDEX_DIGIT(current, r + 1);
   378              Direction nextDir;
   379              if (oldDigit == INVALID_DIGIT) {
   380                  // Only possible on invalid input
   381                  return E_CELL_INVALID;
   382              } else if (isResolutionClassIII(r + 1)) {
   383                  H3_SET_INDEX_DIGIT(current, r + 1, NEW_DIGIT_II[oldDigit][dir]);
   384                  nextDir = NEW_ADJUSTMENT_II[oldDigit][dir];
   385              } else {
   386                  H3_SET_INDEX_DIGIT(current, r + 1,
   387                                     NEW_DIGIT_III[oldDigit][dir]);
   388                  nextDir = NEW_ADJUSTMENT_III[oldDigit][dir];
   389              }
   390
   391              if (nextDir != CENTER_DIGIT) {
   392                  dir = nextDir;
   393                  r--;
   394              } else {
   395                  // No more adjustment to perform
   396                  break;
   397              }
   398          }
   399      }
