   401      int newBaseCell = H3_GET_BASE_CELL(current);
   402      if (_isBaseCellPentagon(newBaseCell)) {
   403          int alreadyAdjustedKSubsequence = 0;
   404
   405          // force rotation out of missing k-axes sub-sequence
   406          if (_h3LeadingNonZeroDigit(current) == K_AXES_DIGIT) {
   407              if (oldBaseCell != newBaseCell) {
   408                  // in this case, we traversed into the deleted
   409                  // k subsequence of a pentagon base cell.
   410                  // We need to rotate out of that case depending
   411                  // on how we got here.
   412                  // check for a cw/ccw offset face; default is ccw
   413
   414                  if (_baseCellIsCwOffset(
   415                          newBaseCell, baseCellData[oldBaseCell].homeFijk.face)) {
   416                      current = _h3Rotate60cw(current);
   417                  } else {
   418                      // See cwOffsetPent in testGridDisk.c for why this is
   419                      // unreachable.
   420                      current = _h3Rotate60ccw(current);  // LCOV_EXCL_LINE
   421                  }
   422                  alreadyAdjustedKSubsequence = 1;
   423              } else {
   424                  // In this case, we traversed into the deleted
   425                  // k subsequence from within the same pentagon
   426                  // base cell.
   427                  if (oldLeadingDigit == CENTER_DIGIT) {
   428                      // Undefined: the k direction is deleted from here
   429                      return E_PENTAGON;
   430                  } else if (oldLeadingDigit == JK_AXES_DIGIT) {
   431                      // Rotate out of the deleted k subsequence
   432                      // We also need an additional change to the direction we're
   433                      // moving in
   434                      current = _h3Rotate60ccw(current);
   435                      *rotations = *rotations + 1;
   436                  } else if (oldLeadingDigit == IK_AXES_DIGIT) {
   437                      // Rotate out of the deleted k subsequence
   438                      // We also need an additional change to the direction we're
   439                      // moving in
